UPDATE "event" AS event
SET "address" = COALESCE(legacy."verifiedAddress", event."address"),
    "lat" = COALESCE(legacy."verifiedLat"::double precision, locality."lat"),
    "lng" = COALESCE(legacy."verifiedLng"::double precision, locality."lng"),
    "isLocationApproximate" = legacy."verifiedAddress" IS NULL,
    "updatedAt" = CURRENT_TIMESTAMP
FROM legacy, "seed_state" AS seed, "locality" AS locality
WHERE seed."key" = 'demo'
    AND event."id" = ANY(seed."eventIds")
    AND event."localityId" = locality."id"
    AND locality."slug" = legacy."localitySlug"
    AND event."title" = legacy."title"
    AND event."address" = legacy."address"
    AND event."lat" = legacy."lat"::double precision
    AND event."lng" = legacy."lng"::double precision;

COMMIT;
